import { Effect } from "effect";
import { z } from "zod";
import type {
	GetV1Routines200,
	GetV1RoutinesRoutineid200,
	GetV1Workouts200,
	GetV1WorkoutsWorkoutid200,
	GetV1RoutinesQuery,
	GetV1WorkoutsQuery,
} from "./types.js";
import type { HevyRequestOptions } from "./execution.js";
import type { RequestConfig, ResponseConfig } from "./fetch.ts";

/**
 * Private attachment used to connect a curated Promise client to its native
 * request interpreter without adding an Effect method to `HevyClient`.
 */
export const NATIVE_REQUEST_EFFECT = Symbol("native-request-effect");

export type NativeRequestEffect = <TData, TVariables = unknown>(
	config: RequestConfig<TVariables> & {
		readonly hevyDeadline?: number;
		readonly hevyTimeoutMs?: number;
	},
) => Effect.Effect<ResponseConfig<TData>, unknown>;

export interface HevyRequestEffectClient {
	getWorkouts(
		params?: GetV1WorkoutsQuery,
		options?: HevyRequestOptions,
	): Effect.Effect<GetV1Workouts200, Error>;
	getWorkout(
		workoutId: string,
		options?: HevyRequestOptions,
	): Effect.Effect<GetV1WorkoutsWorkoutid200, Error>;
	getRoutines(
		params?: GetV1RoutinesQuery,
		options?: HevyRequestOptions,
	): Effect.Effect<GetV1Routines200, Error>;
	getRoutineById(
		routineId: string,
		options?: HevyRequestOptions,
	): Effect.Effect<GetV1RoutinesRoutineid200, Error>;
}

type RequestEffectMethod = (...args: never[]) => void;

type RequestExecutionControl = {
	readonly signal?: AbortSignal;
	readonly hevyDeadline?: number;
	readonly hevyTimeoutMs?: number;
};

type NativeRequestEffectOwner = {
	readonly requestEffect: NativeRequestEffect;
};

type CuratedClientWithNativeRequestEffect = {
	readonly [NATIVE_REQUEST_EFFECT]?: NativeRequestEffect;
} & (
	| { readonly getWorkouts: RequestEffectMethod }
	| { readonly getWorkout: RequestEffectMethod }
	| { readonly getRoutines: RequestEffectMethod }
	| { readonly getRoutineById: RequestEffectMethod }
);

type RequestEffectOwner =
	| NativeRequestEffectOwner
	| CuratedClientWithNativeRequestEffect;

const functionSchema = z.function();

function isNativeRequestEffect(
	value: NativeRequestEffect | undefined,
): value is NativeRequestEffect {
	return functionSchema.safeParse(value).success;
}

/**
 * Return the request interpreter owned by a curated client.
 *
 * This is intentionally available only from the client's internal subpath.
 * The returned interpreter is the same one used by every Promise method on
 * the client, including its retry, timeout, abort, and error behavior.
 */
export function getNativeRequestEffect(
	client: RequestEffectOwner,
): NativeRequestEffect {
	const requestEffect =
		"requestEffect" in client
			? client.requestEffect
			: client[NATIVE_REQUEST_EFFECT];
	if (!isNativeRequestEffect(requestEffect)) {
		throw new TypeError(
			"Expected a Hevy client with the internal request Effect seam",
		);
	}
	return requestEffect;
}

const noExecutionControl = {};

function executionControl(
	options: HevyRequestOptions | undefined,
): RequestExecutionControl {
	if (options === undefined) return noExecutionControl;
	const control = {
		signal: options.signal,
		hevyDeadline: options.deadline,
		hevyTimeoutMs: options.timeoutMs,
	} satisfies RequestExecutionControl;
	return control;
}

function readEffect<TData>(
	requestEffect: NativeRequestEffect,
	config: RequestConfig,
	options?: HevyRequestOptions,
): Effect.Effect<TData, Error> {
	return requestEffect({
		...config,
		...executionControl(options),
	}).pipe(
		Effect.map((response) => response.data as TData),
		Effect.mapError((cause) =>
			cause instanceof Error ? cause : new Error(String(cause)),
		),
	) as Effect.Effect<TData, Error>;
}

/**
 * Build the four read operations used by the runtime-neutral operations
 * package. These methods return Effects, but remain on the internal subpath so
 * public Promise callers and adapters never see the Effect surface.
 */
export function getRequestEffectClient(
	client: RequestEffectOwner,
): HevyRequestEffectClient {
	const requestEffect = getNativeRequestEffect(client);
	return {
		getWorkouts: (params, options) =>
			readEffect<GetV1Workouts200>(
				requestEffect,
				{
					method: "GET",
					url: "/v1/workouts",
					query: params,
				},
				options,
			),
		getWorkout: (workoutId, options) =>
			readEffect<GetV1WorkoutsWorkoutid200>(
				requestEffect,
				{
					method: "GET",
					url: "/v1/workouts/{workoutId}",
					path: { workoutId },
				},
				options,
			),
		getRoutines: (params, options) =>
			readEffect<GetV1Routines200>(
				requestEffect,
				{
					method: "GET",
					url: "/v1/routines",
					query: params,
				},
				options,
			),
		getRoutineById: (routineId, options) =>
			readEffect<GetV1RoutinesRoutineid200>(
				requestEffect,
				{
					method: "GET",
					url: "/v1/routines/{routineId}",
					path: { routineId },
				},
				options,
			),
	};
}

/**
 * Stable internal factory name for consumers that want the Effect read
 * facade. It is deliberately not re-exported from the package's main entry.
 */
export const createRequestEffect = getRequestEffectClient;

import { Schema } from "effect";

/** Typed error vocabulary for Effect-based client integrations. */
export class RateLimitError extends Schema.TaggedError<RateLimitError>()(
	"RateLimitError",
	{
		status: Schema.Number,
		endpoint: Schema.String,
		method: Schema.String,
		retryAfterSeconds: Schema.optional(Schema.Number),
	},
) {}

export class ValidationError extends Schema.TaggedError<ValidationError>()(
	"ValidationError",
	{
		status: Schema.Number,
		endpoint: Schema.String,
		method: Schema.String,
	},
) {}

export class NotFoundError extends Schema.TaggedError<NotFoundError>()(
	"NotFoundError",
	{
		status: Schema.Number,
		endpoint: Schema.String,
		method: Schema.String,
		expected: Schema.Boolean,
	},
) {}

export class NetworkError extends Schema.TaggedError<NetworkError>()(
	"NetworkError",
	{
		code: Schema.String,
		phase: Schema.optional(
			Schema.Union([
				Schema.Literal("before-dispatch"),
				Schema.Literal("dispatch"),
				Schema.Literal("response-headers"),
				Schema.Literal("response-content"),
				Schema.Literal("backoff"),
				Schema.Literal("completed"),
			]),
		),
		operationSafety: Schema.optional(
			Schema.Union([
				Schema.Literal("read"),
				Schema.Literal("idempotent-write"),
				Schema.Literal("non-idempotent-write"),
			]),
		),
		commitState: Schema.optional(
			Schema.Union([
				Schema.Literal("not_sent"),
				Schema.Literal("confirmed"),
				Schema.Literal("unknown"),
			]),
		),
		safeToRetry: Schema.optional(Schema.Boolean),
		outcome: Schema.optional(
			Schema.Union([
				Schema.Literal("success"),
				Schema.Literal("expected"),
				Schema.Literal("retryable_failure"),
				Schema.Literal("terminal_failure"),
				Schema.Literal("cancelled"),
				Schema.Literal("deadline_exceeded"),
			]),
		),
		retryCount: Schema.optional(Schema.Number),
		retryExhausted: Schema.Boolean,
	},
) {}

export class ApiError extends Schema.TaggedError<ApiError>()("ApiError", {
	status: Schema.Number,
	endpoint: Schema.String,
	method: Schema.String,
}) {}

import type { HevyClient } from "@hevy-mcp/hevy-client";
import {
	getRequestEffectClient,
	type HevyRequestEffectClient,
} from "@hevy-mcp/hevy-client/internal";
import {
	createRoutinesGetOperation,
	createRoutinesListOperation,
	type RoutinesGetOperation,
	type RoutinesListOperation,
} from "./routines.js";
import {
	createWorkoutsGetOperation,
	createWorkoutsListOperation,
	type WorkoutsGetOperation,
	type WorkoutsListOperation,
} from "./workouts.js";

export { routinesGetDescriptor, routinesListDescriptor } from "./routines.js";
export { workoutsGetDescriptor, workoutsListDescriptor } from "./workouts.js";

export interface HevyOperations {
	readonly routines: {
		readonly get: RoutinesGetOperation;
		readonly list: RoutinesListOperation;
	};
	readonly workouts: {
		readonly get: WorkoutsGetOperation;
		readonly list: WorkoutsListOperation;
	};
}

export function createOperations(client: HevyClient): HevyOperations {
	let requestEffectClient: HevyRequestEffectClient | undefined;
	const getRequestEffectClientOnce = (): HevyRequestEffectClient => {
		requestEffectClient ??= getRequestEffectClient(client);
		return requestEffectClient;
	};
	const lazyRequestEffectClient: HevyRequestEffectClient = {
		getWorkouts: (...args) => getRequestEffectClientOnce().getWorkouts(...args),
		getWorkout: (...args) => getRequestEffectClientOnce().getWorkout(...args),
		getRoutines: (...args) => getRequestEffectClientOnce().getRoutines(...args),
		getRoutineById: (...args) =>
			getRequestEffectClientOnce().getRoutineById(...args),
	};
	return {
		routines: {
			get: createRoutinesGetOperation(lazyRequestEffectClient),
			list: createRoutinesListOperation(lazyRequestEffectClient),
		},
		workouts: {
			get: createWorkoutsGetOperation(lazyRequestEffectClient),
			list: createWorkoutsListOperation(lazyRequestEffectClient),
		},
	};
}

import { Context } from "effect";
import type { HevyClient } from "@hevy-mcp/hevy-client";
import type { HevyOperations } from "@hevy-mcp/operations";
import type { ToolExecutionContext } from "./execution.js";
import type { ToolObserver } from "./observation.js";
import type { ExerciseTemplateCatalog } from "./utils/exercise-template-catalog.js";

/**
 * Effect service tags for the runtime dependencies used by MCP execution.
 *
 * These tags establish the dependency-injection seam without changing the
 * existing Promise-based runtime. Later migrations can provide these services
 * at the adapter boundary while existing ToolRuntime callers remain intact.
 */
export class HevyClientService extends Context.Service<
	HevyClientService,
	HevyClient
>()("hevy-mcp/core/HevyClient") {}

export class HevyOperationsService extends Context.Service<
	HevyOperationsService,
	HevyOperations
>()("hevy-mcp/core/HevyOperations") {}

export class ExerciseTemplateCatalogService extends Context.Service<
	ExerciseTemplateCatalogService,
	ExerciseTemplateCatalog
>()("hevy-mcp/core/ExerciseTemplateCatalog") {}

export class ToolObserverService extends Context.Service<
	ToolObserverService,
	ToolObserver
>()("hevy-mcp/core/ToolObserver") {}

export class ToolExecutionContextService extends Context.Service<
	ToolExecutionContextService,
	ToolExecutionContext
>()("hevy-mcp/core/ToolExecutionContext") {}

import { Layer } from "effect";
import type { HevyClient } from "@hevy-mcp/hevy-client";
import { createOperations, type HevyOperations } from "@hevy-mcp/operations";
import {
	ExerciseTemplateCatalogService,
	HevyClientService,
	HevyOperationsService,
	ToolExecutionContextService,
	ToolObserverService,
} from "./effect-services.js";
import type { ToolExecutionContext } from "./execution.js";
import type { ToolObserver } from "./observation.js";
import type { ExerciseTemplateCatalog } from "./utils/exercise-template-catalog.js";

export interface CoreServiceLayerOptions {
	readonly client: HevyClient;
	readonly catalog: ExerciseTemplateCatalog;
	readonly execution: ToolExecutionContext;
	readonly operations?: HevyOperations;
}

export type CoreServiceIdentifiers =
	| HevyClientService
	| HevyOperationsService
	| ExerciseTemplateCatalogService
	| ToolExecutionContextService;

export type CoreServiceLayer = Layer.Layer<CoreServiceIdentifiers>;

/**
 * Build the runtime-neutral dependency graph for an Effect program.
 *
 * The returned layer is intentionally request-local. ToolRuntime builds it
 * for each runtime or execution scope rather than installing a process-wide
 * Effect runtime.
 */
export function createCoreServiceLayer({
	client,
	catalog,
	execution,
	operations = createOperations(client),
}: CoreServiceLayerOptions): CoreServiceLayer {
	return Layer.mergeAll(
		Layer.succeed(HevyClientService, client),
		Layer.succeed(HevyOperationsService, operations),
		Layer.succeed(ExerciseTemplateCatalogService, catalog),
		Layer.succeed(ToolExecutionContextService, execution),
	);
}

export function createToolObserverLayer(
	observer: ToolObserver,
): Layer.Layer<ToolObserverService> {
	return Layer.succeed(ToolObserverService, observer);
}

import { Effect } from "effect";
import type {
	HevyExecutionOptions,
	HevyOperationSafety,
} from "@hevy-mcp/hevy-client";
import type { HevyRequestEffectClient } from "@hevy-mcp/hevy-client/internal";
import type { GetV1Workouts200, Workout } from "@hevy-mcp/hevy-client/types";
import {
	isExpectedReadEndOfList,
	isExpectedReadNotFound,
} from "./operation-errors.js";

export interface WorkoutsListInput {
	readonly page: number;
	readonly pageSize: number;
}

export interface WorkoutsListOutput {
	readonly items: Workout[];
	readonly page: number;
	readonly pageCount?: number;
	readonly expected404Outcome?: "end_of_list";
}

export type WorkoutsListAdapter = Pick<HevyRequestEffectClient, "getWorkouts">;

export interface WorkoutsGetInput {
	readonly workoutId: string;
}

export interface WorkoutsGetOutput {
	readonly workout: Workout | null;
	readonly expected404Outcome?: "not_found";
}

export type WorkoutsGetAdapter = Pick<HevyRequestEffectClient, "getWorkout">;

export interface WorkoutsGetDescriptor {
	readonly id: "workouts.get";
	readonly safety: Extract<HevyOperationSafety, "read">;
}

export const workoutsGetDescriptor: WorkoutsGetDescriptor = {
	id: "workouts.get",
	safety: "read",
};

export interface WorkoutsGetOperation {
	readonly descriptor: WorkoutsGetDescriptor;
	execute(
		input: WorkoutsGetInput,
		options?: HevyExecutionOptions,
	): Promise<WorkoutsGetOutput>;
}

export interface WorkoutsListDescriptor {
	readonly id: "workouts.list";
	readonly safety: Extract<HevyOperationSafety, "read">;
}

export const workoutsListDescriptor: WorkoutsListDescriptor = {
	id: "workouts.list",
	safety: "read",
};

export interface WorkoutsListOperation {
	readonly descriptor: WorkoutsListDescriptor;
	execute(
		input: WorkoutsListInput,
		options?: HevyExecutionOptions,
	): Promise<WorkoutsListOutput>;
}

function normalizeWorkoutsPage(
	response: GetV1Workouts200,
	input: WorkoutsListInput,
): WorkoutsListOutput {
	if (response.page !== undefined && response.page !== input.page) {
		throw new Error(
			`Workouts page mismatch: requested page ${input.page} but received page ${response.page}`,
		);
	}
	return {
		items: response.workouts ?? [],
		page: response.page ?? input.page,
		pageCount: response.page_count,
	};
}

export function createWorkoutsGetOperation(
	adapter: WorkoutsGetAdapter,
): WorkoutsGetOperation {
	return {
		descriptor: workoutsGetDescriptor,
		async execute(input, options) {
			const program = (
				options === undefined
					? adapter.getWorkout(input.workoutId)
					: adapter.getWorkout(input.workoutId, options)
			).pipe(
				Effect.map((response) => ({ workout: response ?? null })),
				Effect.catchIf(
					(error) => isExpectedReadNotFound(error, "/v1/workouts"),
					() =>
						Effect.succeed({
							workout: null,
							expected404Outcome: "not_found" as const,
						}),
				),
			);
			return Effect.runPromise(program);
		},
	};
}

export function createWorkoutsListOperation(
	adapter: WorkoutsListAdapter,
): WorkoutsListOperation {
	return {
		descriptor: workoutsListDescriptor,
		async execute(input, options) {
			const params = { page: input.page, pageSize: input.pageSize };
			const program = (
				options === undefined
					? adapter.getWorkouts(params)
					: adapter.getWorkouts(params, options)
			).pipe(
				Effect.map((response) => normalizeWorkoutsPage(response, input)),
				Effect.catchIf(
					(error) => isExpectedReadEndOfList(error, "/v1/workouts", input.page),
					() =>
						Effect.succeed({
							items: [],
							page: input.page,
							pageCount: undefined,
							expected404Outcome: "end_of_list" as const,
						}),
				),
			);
			return Effect.runPromise(program);
		},
	};
}

