	| "before-dispatch"
	| "dispatch"
	| "response-headers"
	| "response-content"
	| "backoff"
	| "completed";

export type HevyCommitState = "not_sent" | "confirmed" | "unknown";

export type HevyExecutionOutcome =
	| "success"
	| "expected"
	| "retryable_failure"
	| "terminal_failure"
	| "cancelled"
	| "deadline_exceeded";

